                dist[v] = dist[u] + w;
                changed = true;
            }
        }
        if (!changed) break;
    }
    let ans = 0;
    for (let i = 1; i <= n; i++) {
        if (dist[i] === Infinity) return -1;
        ans = Math.max(ans, dist[i]);
    }
    return ans;
};

