class Solution {

    public List<String> findItinerary(List<List<String>> tickets) {
        Map<String, List<String>> adj = new HashMap<>();
        for (List<String> t : tickets)
            adj.computeIfAbsent(t.get(0), x -> new ArrayList<>()).add(
                t.get(1)
            );
        for (List<String> list : adj.values()) Collections.sort(list);
        List<String> path = new ArrayList<>();
        path.add("JFK");
        dfs("JFK", adj, path, tickets.size() + 1);
        return path;
    }

    private boolean dfs(
        String u,
        Map<String, List<String>> adj,
        List<String> path,
        int target
    ) {
        if (path.size() == target) return true; // all tickets used
        List<String> next = adj.get(u);
        if (next == null) return false;
        for (int i = 0; i < next.size(); i++) {
            if (i > 0 && next.get(i).equals(next.get(i - 1))) continue; // same choice already failed

            String v = next.remove(i); // use this ticket
            path.add(v);
            if (dfs(v, adj, path, target)) return true;
            path.remove(path.size() - 1); // undo
            next.add(i, v);
        }
        return false;
    }
}

