var findItinerary = function (tickets) {
    const adj = new Map();
    for (const [a, b] of tickets) {
        if (!adj.has(a)) adj.set(a, []);
        adj.get(a).push(b);
    }
    for (const list of adj.values()) list.sort();
    const path = ["JFK"];
    const target = tickets.length + 1;

    const dfs = (u) => {
        if (path.length === target) return true;
        const next = adj.get(u);
        if (!next) return false;
        for (let i = 0; i < next.length; i++) {
            if (i > 0 && next[i] === next[i - 1]) continue;
            const v = next.splice(i, 1)[0]; // use ticket
            path.push(v);
            if (dfs(v)) return true;
            path.pop(); // undo
            next.splice(i, 0, v);
        }
        return false;
    };
    dfs("JFK");
    return path;
};

