class Solution {

    public List<String> findItinerary(List<List<String>> tickets) {
        Map<String, PriorityQueue<String>> adj = new HashMap<>();

        for (List<String> t : tickets)
            adj.computeIfAbsent(t.get(0), x ->
                new PriorityQueue<>()
            ).offer(t.get(1));
        LinkedList<String> route = new LinkedList<>();
        dfs("JFK", adj, route);
        return route;
    }

    private void dfs(
        String u,
        Map<String, PriorityQueue<String>> adj,
        LinkedList<String> route
    ) {
        PriorityQueue<String> pq = adj.get(u);
        while (pq != null && !pq.isEmpty()) dfs(pq.poll(), adj, route); // smallest unused ticket first
        route.addFirst(u); // post-order: added only when u has no tickets left
    }
}

