var findItinerary = function (tickets) {
    const adj = new Map();
    for (const [a, b] of tickets) {
        if (!adj.has(a)) adj.set(a, []);
        adj.get(a).push(b);
    }
    // sort descending so pop() gives the lexically smallest destination
    for (const list of adj.values())
        list.sort((x, y) => (x < y ? 1 : x > y ? -1 : 0));
    const route = [];
    const dfs = (u) => {
        const next = adj.get(u);
        while (next && next.length > 0) dfs(next.pop());
        route.push(u); // post-order
    };
    dfs("JFK");
    return route.reverse();
};

