class Solution {

    private static final int[][] DIRS = {
        { 1, 0 },
        { -1, 0 },
        { 0, 1 },
        { 0, -1 },
    };

    public int swimInWater(int[][] grid) {
        int n = grid.length;
        for (
            int t = Math.max(grid[0][0], grid[n - 1][n - 1]);
            ;
            t++
        ) if (canReach(grid, t)) return t; // t = n*n-1 always works, so this terminates
    }

    private boolean canReach(int[][] grid, int t) {
        int n = grid.length;
        if (grid[0][0] > t) return false;
        boolean[][] seen = new boolean[n][n];
        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[] { 0, 0 });
        seen[0][0] = true;
        while (!q.isEmpty()) {
            int[] c = q.poll();
            if (c[0] == n - 1 && c[1] == n - 1) return true;
            for (int[] d : DIRS) {
                int r = c[0] + d[0],
                    col = c[1] + d[1];
                if (
                    r < 0 ||
                    col < 0 ||
                    r >= n ||
                    col >= n ||
                    seen[r][col] ||
                    grid[r][col] > t
                ) continue;
                seen[r][col] = true;
                q.offer(new int[] { r, col });
            }
        }
        return false;
    }
}

