class Solution {

    private static final int[][] DIRS = {
        { 1, 0 },
        { -1, 0 },
        { 0, 1 },
        { 0, -1 },
    };

    public int swimInWater(int[][] grid) {
        int n = grid.length;
        int lo = Math.max(grid[0][0], grid[n - 1][n - 1]),
            hi = n * n - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;

            if (canReach(grid, mid)) hi = mid;
            // mid works, try smaller
            else lo = mid + 1;
        }
        return lo;
    }

    private boolean canReach(int[][] grid, int t) {
        int n = grid.length;
        if (grid[0][0] > t) return false;
        boolean[][] seen = new boolean[n][n];
        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[] { 0, 0 });
        seen[0][0] = true;
        while (!q.isEmpty()) {
            int[] c = q.poll();
            if (c[0] == n - 1 && c[1] == n - 1) return true;
            for (int[] d : DIRS) {
                int r = c[0] + d[0],
                    col = c[1] + d[1];
                if (
                    r < 0 ||
                    col < 0 ||
                    r >= n ||
                    col >= n ||
                    seen[r][col] ||
                    grid[r][col] > t
                ) continue;
                seen[r][col] = true;
                q.offer(new int[] { r, col });
            }
        }
        return false;
    }
}

