class Solution {

    public String alienOrder(String[] words) {
        boolean[] present = new boolean[26];
        boolean[][] edge = new boolean[26][26];
        for (String w : words)
            for (char c : w.toCharArray()) present[c - 'a'] = true;
        for (int i = 0; i + 1 < words.length; i++) {
            String a = words[i],
                b = words[i + 1];
            if (a.length() > b.length() && a.startsWith(b)) return ""; // "abc" before "ab": invalid
            for (int j = 0; j < Math.min(a.length(), b.length()); j++) {
                if (a.charAt(j) != b.charAt(j)) {
                    edge[a.charAt(j) - 'a'][b.charAt(j) - 'a'] = true; // first difference only
                    break;
                }
            }
        }
        int total = 0;
        for (boolean p : present) if (p) total++;
        boolean[] used = new boolean[26];
        StringBuilder sb = new StringBuilder();
        while (sb.length() < total) {
            int pick = -1;
            for (int v = 0; v < 26 && pick == -1; v++) {
                if (!present[v] || used[v]) continue;
                boolean free = true;
                for (int u = 0; u < 26; u++) if (
                    present[u] && !used[u] && edge[u][v]
                ) {
                    free = false;
                    break;
                }
                if (free) pick = v;
            }
            if (pick == -1) return ""; // every remaining letter has a predecessor: cycle
            used[pick] = true;
            sb.append((char) ('a' + pick));
        }
        return sb.toString();
    }
}

