var alienOrder = function (words) {
    const present = new Array(26).fill(false);
    const edge = Array.from({ length: 26 }, () =>
        new Array(26).fill(false),
    );
    const idx = (ch) => ch.charCodeAt(0) - 97;
    for (const w of words) for (const ch of w) present[idx(ch)] = true;
    for (let i = 0; i + 1 < words.length; i++) {
        const a = words[i],
            b = words[i + 1];
        if (a.length > b.length && a.startsWith(b)) return "";
        for (let j = 0; j < Math.min(a.length, b.length); j++) {
            if (a[j] !== b[j]) {
                edge[idx(a[j])][idx(b[j])] = true;
                break;
            }
        }
    }
    const total = present.filter(Boolean).length;
    const used = new Array(26).fill(false);
    let res = "";
    while (res.length < total) {
        let pick = -1;
        for (let v = 0; v < 26 && pick === -1; v++) {
            if (!present[v] || used[v]) continue;
            let free = true;
            for (let u = 0; u < 26; u++)
                if (present[u] && !used[u] && edge[u][v]) {
                    free = false;
                    break;
                }
            if (free) pick = v;
        }
        if (pick === -1) return "";
        used[pick] = true;
        res += String.fromCharCode(97 + pick);
    }
    return res;
};

