class Solution {

    public String alienOrder(String[] words) {
        boolean[] present = new boolean[26];
        boolean[][] edge = new boolean[26][26];
        int[] indeg = new int[26];
        for (String w : words)
            for (char c : w.toCharArray()) present[c - 'a'] = true;
        for (int i = 0; i + 1 < words.length; i++) {
            String a = words[i],
                b = words[i + 1];
            if (a.length() > b.length() && a.startsWith(b)) return "";
            for (int j = 0; j < Math.min(a.length(), b.length()); j++) {
                int x = a.charAt(j) - 'a',
                    y = b.charAt(j) - 'a';
                if (x != y) {
                    if (!edge[x][y]) {
                        edge[x][y] = true;
                        indeg[y]++;
                    } // count each edge once
                    break;
                }
            }
        }
        Deque<Integer> q = new ArrayDeque<>();
        int total = 0;
        for (int c = 0; c < 26; c++) {
            if (!present[c]) continue;
            total++;
            if (indeg[c] == 0) q.offer(c);
        }
        StringBuilder sb = new StringBuilder();
        while (!q.isEmpty()) {
            int u = q.poll();
            sb.append((char) ('a' + u));
            for (int v = 0; v < 26; v++) {
                if (edge[u][v] && --indeg[v] == 0) q.offer(v);
            }
        }
        return sb.length() == total ? sb.toString() : ""; // shorter means a cycle
    }
}

