var alienOrder = function (words) {
    const present = new Array(26).fill(false);
    const adj = Array.from({ length: 26 }, () => new Set());
    const indeg = new Array(26).fill(0);
    const idx = (ch) => ch.charCodeAt(0) - 97;
    for (const w of words) for (const ch of w) present[idx(ch)] = true;
    for (let i = 0; i + 1 < words.length; i++) {
        const a = words[i],
            b = words[i + 1];
        if (a.length > b.length && a.startsWith(b)) return "";
        for (let j = 0; j < Math.min(a.length, b.length); j++) {
            const x = idx(a[j]),
                y = idx(b[j]);
            if (x !== y) {
                if (!adj[x].has(y)) {
                    adj[x].add(y);
                    indeg[y]++;
                }
                break;
            }
        }
    }
    const q = [];
    let total = 0;
    for (let c = 0; c < 26; c++) {
        if (!present[c]) continue;
        total++;
        if (indeg[c] === 0) q.push(c);
    }
    let res = "";
    for (let head = 0; head < q.length; head++) {
        const u = q[head];
        res += String.fromCharCode(97 + u);
        for (const v of adj[u]) if (--indeg[v] === 0) q.push(v);
    }
    return res.length === total ? res : "";
};

