class Solution {

    private int best;

    public int findCheapestPrice(
        int n,
        int[][] flights,
        int src,
        int dst,
        int k
    ) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] f : flights)
            adj.get(f[0]).add(new int[] { f[1], f[2] });
        best = Integer.MAX_VALUE;
        boolean[] onPath = new boolean[n];
        onPath[src] = true;
        dfs(src, dst, k + 1, 0, adj, onPath);
        return best == Integer.MAX_VALUE ? -1 : best;
    }

    private void dfs(
        int u,
        int dst,
        int flightsLeft,
        int cost,
        List<List<int[]>> adj,
        boolean[] onPath
    ) {
        if (u == dst) {
            best = Math.min(best, cost);
            return;
        }
        if (flightsLeft == 0) return;
        for (int[] e : adj.get(u)) {
            int v = e[0],
                nc = cost + e[1];
            if (onPath[v] || nc >= best) continue; // prune cycles and hopeless routes
            onPath[v] = true;
            dfs(v, dst, flightsLeft - 1, nc, adj, onPath);

            onPath[v] = false;
        }
    }
}

