        if (flightsLeft === 0) return;
        for (const [v, w] of adj[u]) {
            if (onPath[v] || cost + w >= best) continue;
            onPath[v] = true;
            dfs(v, flightsLeft - 1, cost + w);
            onPath[v] = false;
        }
    };
    onPath[src] = true;
    dfs(src, k + 1, 0);
    return best === Infinity ? -1 : best;
};

