class Solution {

    public int[] shortestPath(int V, int E, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[V];
        for (int[] e : edges) {
            adj.get(e[0]).add(new int[] { e[1], e[2] });
            indeg[e[1]]++;
        }

        int[] topo = new int[V];
        int idx = 0;
        Deque<Integer> q = new ArrayDeque<>();
        for (int i = 0; i < V; i++) if (indeg[i] == 0) q.offer(i);
        while (!q.isEmpty()) {
            int u = q.poll();
            topo[idx++] = u;
            for (int[] e : adj.get(u))
                if (--indeg[e[0]] == 0) q.offer(e[0]);
        }

        final int INF = Integer.MAX_VALUE;
        int[] dist = new int[V];
        Arrays.fill(dist, INF);
        dist[0] = 0;
        for (int u : topo) {
            if (dist[u] == INF) continue; // not reachable from 0
            for (int[] e : adj.get(u)) // dist[u] is final here: all incoming edges were processed
                if (dist[u] + e[1] < dist[e[0]]) dist[e[0]] =
                    dist[u] + e[1];
        }
        for (int i = 0; i < V; i++) if (dist[i] == INF) dist[i] = -1;
        return dist;
    }
}

