class Solution {

    private static final int[][] DIRS = {
        { 1, 0 },
        { -1, 0 },
        { 0, 1 },
        { 0, -1 },
    };
    private int best;

    public int minimumEffortPath(int[][] heights) {
        best = Integer.MAX_VALUE;
        boolean[][] onPath =
            new boolean[heights.length][heights[0].length];
        onPath[0][0] = true;
        dfs(heights, 0, 0, 0, onPath);
        return best;
    }

    private void dfs(
        int[][] h,
        int r,
        int c,
        int effort,
        boolean[][] onPath
    ) {
        if (effort >= best) return; // cannot improve
        if (r == h.length - 1 && c == h[0].length - 1) {
            best = effort;
            return;
        }
        for (int[] d : DIRS) {
            int nr = r + d[0],
                nc = c + d[1];
            if (
                nr < 0 ||
                nc < 0 ||
                nr >= h.length ||
                nc >= h[0].length ||
                onPath[nr][nc]
            ) continue;
            onPath[nr][nc] = true;

            dfs(
                h,
                nr,
                nc,
                Math.max(effort, Math.abs(h[nr][nc] - h[r][c])),
                onPath
            );
            onPath[nr][nc] = false; // backtrack
        }
    }
}

