        for (const [dr, dc] of DIRS) {
            const nr = r + dr,
                nc = c + dc;
            if (
                nr < 0 ||
                nc < 0 ||
                nr >= R ||
                nc >= C ||
                onPath[nr][nc]
            )
                continue;
            onPath[nr][nc] = true;
            dfs(
