                Math.max(
                    effort,
                    Math.abs(heights[nr][nc] - heights[r][c]),
                ),
            );
            onPath[nr][nc] = false;
        }
    };
    onPath[0][0] = true;
    dfs(0, 0, 0);
    return best;
};

