class Solution {

    private static final int[][] DIRS = {
        { 1, 0 },
        { -1, 0 },
        { 0, 1 },
        { 0, -1 },
    };

    public int minimumEffortPath(int[][] heights) {
        int lo = 0,
            hi = 1_000_000;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (canReach(heights, mid)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }

    private boolean canReach(int[][] h, int limit) {
        int R = h.length,
            C = h[0].length;
        boolean[][] seen = new boolean[R][C];

        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[] { 0, 0 });
        seen[0][0] = true;
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            if (cur[0] == R - 1 && cur[1] == C - 1) return true;
            for (int[] d : DIRS) {
                int nr = cur[0] + d[0],
                    nc = cur[1] + d[1];
                if (
                    nr < 0 ||
                    nc < 0 ||
                    nr >= R ||
                    nc >= C ||
                    seen[nr][nc]
                ) continue;
                if (
                    Math.abs(h[nr][nc] - h[cur[0]][cur[1]]) > limit
                ) continue; // edge too steep
                seen[nr][nc] = true;
                q.offer(new int[] { nr, nc });
            }
        }
        return false;
    }
}

