class Solution {
    public int minimumEffortPath(int[][] heights) {
        int R = heights.length, C = heights[0].length;
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        int[][] dist = new int[R][C];
        for (int[] row : dist) Arrays.fill(row, Integer.MAX_VALUE);
        dist[0][0] = 0;
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0])); // {effort, r,
        c}
    pq.offer(new int[]{0, 0, 0});
    while (!pq.isEmpty()) {
        int[] cur = pq.poll();
        int e = cur[0], r = cur[1], c = cur[2];
        if (e > dist[r][c]) continue; // stale
        if (r == R - 1 && c == C - 1) return e; // first pop of target is optimal
        for (int[] d : dirs) {
            int nr = r + d[0], nc = c + d[1];
            if (nr < 0 || nc < 0 || nr >= R || nc >= C) continue;
            int ne = Math.max(e, Math.abs(heights[nr][nc] - heights[r][c])); // cost = max edge on path
            if (ne < dist[nr][nc]) {
                dist[nr][nc] = ne;
                pq.offer(new int[]{ne, nr, nc});
            }
        }
    }
    return 0; // unreachable for valid input
}
}

