class Solution {

    public int[] bellmanFord(int V, int[][] edges, int src) {
        final int INF = 100000000;
        int[] dist = new int[V];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        for (int round = 1; round <= V - 1; round++) {
            for (int[] e : edges) {
                int u = e[0],
                    v = e[1],
                    w = e[2];
                if (dist[u] != INF && dist[u] + w < dist[v]) dist[v] =
                    dist[u] + w;
            }
        }
        for (int[] e : edges) {
            // V-th round: any improvement means a negative cycle
            if (
                dist[e[0]] != INF && dist[e[0]] + e[2] < dist[e[1]]
            ) return new int[] { -1 };
        }

        return dist;
    }
}

