    public int[] bellmanFord(int V, int[][] edges, int src) {
        final int INF = 100000000;
        int[] dist = new int[V];
        Arrays.fill(dist, INF);
        dist[src] = 0;
        for (int round = 1; round <= V; round++) {
            boolean changed = false;
            for (int[] e : edges) {
                int u = e[0],
                    v = e[1],
                    w = e[2];
                if (dist[u] != INF && dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    changed = true;
                }
            }
            if (!changed) return dist; // stable: done, and no reachable negative cycle
            if (round == V) return new int[] { -1 }; // still improving after V-1 rounds
        }
        return dist;
    }
}

