class Solution {

    public void floydWarshall(int[][] dist) {
        final int INF = 100000000;
        int n = dist.length;
        List<int[]> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) for (int j = 0; j < n; j++) if (
            i != j && dist[i][j] != INF
        ) edges.add(new int[] { i, j, dist[i][j] });
        int[][] res = new int[n][n];
        for (int s = 0; s < n; s++) {
            // Bellman-Ford from every source

            int[] d = res[s];
            Arrays.fill(d, INF);
            d[s] = 0;
            for (int round = 1; round < n; round++) {
                boolean changed = false;
                for (int[] e : edges) {
                    if (d[e[0]] != INF && d[e[0]] + e[2] < d[e[1]]) {
                        d[e[1]] = d[e[0]] + e[2];
                        changed = true;
                    }
                }
                if (!changed) break;
            }
        }
        for (int i = 0; i < n; i++) System.arraycopy(
            res[i],
            0,
            dist[i],
            0,
            n
        ); // write back in place
    }
}

