function floydWarshall(dist) {
    const INF = 1e8,
        n = dist.length;
    const edges = [];
    for (let i = 0; i < n; i++)
        for (let j = 0; j < n; j++)
            if (i !== j && dist[i][j] !== INF)
                edges.push([i, j, dist[i][j]]);
    const res = [];
    for (let s = 0; s < n; s++) {
        const d = new Array(n).fill(INF);
        d[s] = 0;
        for (let round = 1; round < n; round++) {
            let changed = false;
            for (const [u, v, w] of edges) {
                if (d[u] !== INF && d[u] + w < d[v]) {
                    d[v] = d[u] + w;
                    changed = true;
                }
            }
            if (!changed) break;
        }
        res.push(d);
    }
    for (let i = 0; i < n; i++)
        for (let j = 0; j < n; j++) dist[i][j] = res[i][j];
}

