class Solution {

    public void floydWarshall(int[][] dist) {
        final int INF = 100000000;
        int n = dist.length;
        for (int k = 0; k < n; k++) {
            // allow k as an intermediate vertex

            for (int i = 0; i < n; i++) {
                if (dist[i][k] == INF) continue; // no path i -> k
                for (int j = 0; j < n; j++) {
                    if (dist[k][j] == INF) continue;
                    if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][
                        j
                    ] = dist[i][k] + dist[k][j];
                }
            }
        }
    }
}

