class Solution {

    public List<List<String>> findLadders(
        String beginWord,
        String endWord,
        List<String> wordList
    ) {
        Set<String> dict = new HashSet<>(wordList);
        List<List<String>> res = new ArrayList<>();
        if (!dict.contains(endWord)) return res;
        dict.remove(beginWord);
        Deque<List<String>> q = new ArrayDeque<>();
        q.offer(new ArrayList<>(List.of(beginWord)));
        boolean found = false;
        while (!q.isEmpty() && !found) {
            int size = q.size();
            List<String> usedThisLevel = new ArrayList<>();
            for (int s = 0; s < size; s++) {
                List<String> path = q.poll();

                String last = path.get(path.size() - 1);
                if (last.equals(endWord)) {
                    res.add(path);
                    found = true;
                    continue;
                }
                char[] arr = last.toCharArray();
                for (int i = 0; i < arr.length; i++) {
                    char orig = arr[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        arr[i] = c;
                        String nw = new String(arr);
                        if (dict.contains(nw)) {
                            List<String> next = new ArrayList<>(path); // copy the whole path
                            next.add(nw);
                            q.offer(next);
                            usedThisLevel.add(nw);
                        }
                    }
                    arr[i] = orig;
                }
            }
            for (String w : usedThisLevel) dict.remove(w); // delete only after the level ends
        }
        return res;
    }
}

