var findLadders = function (beginWord, endWord, wordList) {
    const dict = new Set(wordList);
    const res = [];
    if (!dict.has(endWord)) return res;
    dict.delete(beginWord);
    let level = [[beginWord]];
    const A = "abcdefghijklmnopqrstuvwxyz";
    while (level.length > 0) {
        const nextLevel = [];
        const used = [];
        for (const path of level) {
            const last = path[path.length - 1];
            if (last === endWord) {
                res.push(path);
                continue;
            }
            for (let i = 0; i < last.length; i++) {
                for (const ch of A) {
                    const nw =
                        last.slice(0, i) + ch + last.slice(i + 1);
                    if (dict.has(nw)) {
                        nextLevel.push([...path, nw]);
                        used.push(nw);
                    }
                }
            }
        }
        if (res.length > 0) return res; // shortest level reached
        for (const w of used) dict.delete(w);
        level = nextLevel;
    }
    return res;
};

