class Solution {

    public List<List<String>> findLadders(
        String beginWord,
        String endWord,
        List<String> wordList
    ) {
        Set<String> dict = new HashSet<>(wordList);
        List<List<String>> res = new ArrayList<>();
        if (!dict.contains(endWord)) return res;
        Map<String, Integer> depth = new HashMap<>();
        depth.put(beginWord, 0);
        dict.remove(beginWord);
        Deque<String> q = new ArrayDeque<>();
        q.offer(beginWord);
        while (!q.isEmpty()) {
            String w = q.poll();
            if (w.equals(endWord)) break; // all depths up to endWord's level are final
            int d = depth.get(w);
            char[] arr = w.toCharArray();
            for (int i = 0; i < arr.length; i++) {
                char orig = arr[i];
                for (char c = 'a'; c <= 'z'; c++) {
                    arr[i] = c;
                    String nw = new String(arr);
                    if (dict.remove(nw)) {
                        // first visit fixes the depth
                        depth.put(nw, d + 1);
                        q.offer(nw);
                    }
                }
                arr[i] = orig;
            }
        }
        if (!depth.containsKey(endWord)) return res;
        LinkedList<String> path = new LinkedList<>();
        path.add(endWord);
        backtrack(endWord, beginWord, depth, path, res);
        return res;
    }

    private void backtrack(
        String w,
        String begin,
        Map<String, Integer> depth,
        LinkedList<String> path,
        List<List<String>> res
    ) {
        if (w.equals(begin)) {
            res.add(new ArrayList<>(path));
            return;
        }
        int d = depth.get(w);
        char[] arr = w.toCharArray();
        for (int i = 0; i < arr.length; i++) {
            char orig = arr[i];
            for (char c = 'a'; c <= 'z'; c++) {
                arr[i] = c;
                String prev = new String(arr);
                Integer pd = depth.get(prev);
                if (pd != null && pd == d - 1) {
                    // one level closer to beginWord
                    path.addFirst(prev);

                    backtrack(prev, begin, depth, path, res);
                    path.removeFirst();
                }
            }
            arr[i] = orig;
        }
    }
}

