var findLadders = function (beginWord, endWord, wordList) {
    const dict = new Set(wordList);
    const res = [];
    if (!dict.has(endWord)) return res;
    const A = "abcdefghijklmnopqrstuvwxyz";
    const depth = new Map([[beginWord, 0]]);
    dict.delete(beginWord);
    const q = [beginWord];
    for (let head = 0; head < q.length; head++) {
        const w = q[head];
        if (w === endWord) break;
        const d = depth.get(w);
        for (let i = 0; i < w.length; i++) {
            for (const ch of A) {
                const nw = w.slice(0, i) + ch + w.slice(i + 1);
                if (dict.has(nw)) {
                    dict.delete(nw);
                    depth.set(nw, d + 1);
                    q.push(nw);
                }
            }
        }
    }
    if (!depth.has(endWord)) return res;
    const path = [endWord]; // built backwards, reversed when recorded
    const backtrack = (w) => {
        if (w === beginWord) {
            res.push([...path].reverse());
            return;
        }
        const d = depth.get(w);
        for (let i = 0; i < w.length; i++) {
            for (const ch of A) {
                const prev = w.slice(0, i) + ch + w.slice(i + 1);
                if (depth.get(prev) === d - 1) {
                    path.push(prev);
                    backtrack(prev);
                    path.pop();
                }
            }
        }
    };
    backtrack(endWord);
    return res;
};

