class DisjointSet {

    private final int[] parent, rank, size;

    public DisjointSet(int n) {
        parent = new int[n + 1];
        rank = new int[n + 1];
        size = new int[n + 1];
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    public int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]); // path compression
        return parent[x];
    }

    public boolean unionByRank(int u, int v) {
        int ru = find(u),
            rv = find(v);
        if (ru == rv) return false; // already in the same set
        if (rank[ru] < rank[rv]) parent[ru] = rv;
        else if (rank[ru] > rank[rv]) parent[rv] = ru;
        else {
            parent[rv] = ru;
            rank[ru]++;
        } // equal height: tree grows by 1
        return true;
    }

    public boolean unionBySize(int u, int v) {
        int ru = find(u),
            rv = find(v);
        if (ru == rv) return false;
        if (size[ru] < size[rv]) {
            int t = ru;
            ru = rv;
            rv = t;
        } // ru is the bigger tree
        parent[rv] = ru;
        size[ru] += size[rv];
        return true;
    }

    public int sizeOf(int x) {
        return size[find(x)];
    }

    public boolean connected(int u, int v) {
        return find(u) == find(v);
    }
}

