            rv = this.find(v);
        if (ru === rv) return false;
        if (this.rank[ru] < this.rank[rv]) this.parent[ru] = rv;
        else if (this.rank[ru] > this.rank[rv]) this.parent[rv] = ru;
        else {
            this.parent[rv] = ru;
            this.rank[ru]++;
        }
        return true;
    }
    unionBySize(u, v) {
        let ru = this.find(u),
            rv = this.find(v);
        if (ru === rv) return false;
        if (this.size[ru] < this.size[rv]) [ru, rv] = [rv, ru];
        this.parent[rv] = ru;
        this.size[ru] += this.size[rv];
        return true;
    }
    sizeOf(x) {
        return this.size[this.find(x)];
    }
    connected(u, v) {
        return this.find(u) === this.find(v);
    }
