class Solution {

    public int spanningTree(int V, int[][] edges) {
        final int INF = Integer.MAX_VALUE;
        int[][] w = new int[V][V];
        for (int[] row : w) Arrays.fill(row, INF);
        for (int[] e : edges) {
            // keep the cheapest parallel edge
            w[e[0]][e[1]] = Math.min(w[e[0]][e[1]], e[2]);
            w[e[1]][e[0]] = Math.min(w[e[1]][e[0]], e[2]);
        }
        int[] key = new int[V];
        boolean[] inTree = new boolean[V];
        Arrays.fill(key, INF);
        key[0] = 0;
        int total = 0;
        for (int round = 0; round < V; round++) {
            int u = -1;
            for (int i = 0; i < V; i++) if (
                !inTree[i] && (u == -1 || key[i] < key[u])
            ) u = i;
            inTree[u] = true;
            total += key[u];
            for (int v = 0; v < V; v++) if (
                !inTree[v] && w[u][v] < key[v]
            ) key[v] = w[u][v];
        }
        return total;
    }
}

