class Solution {
    public int spanningTree(int V, int[][] edges) {
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < V; i++) adj.add(new ArrayList<>());
        for (int[] e : edges) { adj.get(e[0]).add(new int[]{e[1], e[2]}); adj.get(e[1]).add(new int[]{e[0],
                e[2]}); }
        boolean[] inTree = new boolean[V];
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0])); // {weight,
        node}
    pq.offer(new int[]{0, 0});
    int total = 0;
    while (!pq.isEmpty()) {
        int[] cur = pq.poll();

        int w = cur[0], u = cur[1];
        if (inTree[u]) continue; // a cheaper edge already brought u in
        inTree[u] = true;
        total += w;
        for (int[] e : adj.get(u)) if (!inTree[e[0]]) pq.offer(new int[]{e[1], e[0]});
    }
    return total;
}
}

