function spanningTree(V, edges) {
    const adj = Array.from({ length: V }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }
    const inTree = new Array(V).fill(false);
    const pq = new MinHeap();
    pq.push([0, 0]);
    let total = 0;
    while (pq.size() > 0) {
        const [w, u] = pq.pop();
        if (inTree[u]) continue;
        inTree[u] = true;
        total += w;
        for (const [v, c] of adj[u]) if (!inTree[v]) pq.push([c, v]);
    }
    return total;
}

