class Solution {

    private int[] parent, size;

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    private boolean union(int a, int b) {
        int ra = find(a),
            rb = find(b);
        if (ra == rb) return false; // edge would close a cycle
        if (size[ra] < size[rb]) {
            int t = ra;
            ra = rb;
            rb = t;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
        return true;
    }

    public int spanningTree(int V, int[][] edges) {
        parent = new int[V];
        size = new int[V];
        for (int i = 0; i < V; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        int[][] sorted = edges.clone();
        Arrays.sort(sorted, (a, b) -> Integer.compare(a[2], b[2])); // cheapest first
        int total = 0,
            used = 0;
        for (int[] e : sorted) {
            if (union(e[0], e[1])) {
                total += e[2];
                if (++used == V - 1) break; // tree complete
            }
        }
        return total;
    }
}

