class Solution {

    public int makeConnected(int n, int[][] connections) {
        if (connections.length < n - 1) return -1; // not enough cables
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] c : connections) {
            adj.get(c[0]).add(c[1]);
            adj.get(c[1]).add(c[0]);
        }
        boolean[] seen = new boolean[n];
        int components = 0;
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            components++;
            Deque<Integer> stack = new ArrayDeque<>(); // iterative DFS
            stack.push(i);
            seen[i] = true;
            while (!stack.isEmpty()) {
                int u = stack.pop();
                for (int v : adj.get(u))
                    if (!seen[v]) {
                        seen[v] = true;
                        stack.push(v);
                    }
            }
        }
        return components - 1;
    }
}

