    if (connections.length < n - 1) return -1;
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of connections) {
        adj[a].push(b);
        adj[b].push(a);
    }
    const seen = new Array(n).fill(false);
    let components = 0;
    for (let i = 0; i < n; i++) {
        if (seen[i]) continue;
        components++;
        const stack = [i];
        seen[i] = true;
        while (stack.length) {
            const u = stack.pop();
            for (const v of adj[u])
                if (!seen[v]) {
                    seen[v] = true;
                    stack.push(v);
                }
        }
    }
    return components - 1;
};

