        if (ra == rb) return false;
        if (size[ra] < size[rb]) {
            int t = ra;
            ra = rb;
            rb = t;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
        return true;
    }

    public int makeConnected(int n, int[][] connections) {
        parent = new int[n];

        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        int components = n,
            extra = 0;
        for (int[] c : connections) {
            if (union(c[0], c[1])) components--;
            // merged two groups
            else extra++; // redundant cable we can move
        }
        return extra >= components - 1 ? components - 1 : -1;
    }
}

