class Solution {

    public List<Integer> numIslands2(int m, int n, int[][] positions) {
        boolean[][] land = new boolean[m][n];
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        List<Integer> res = new ArrayList<>();
        for (int[] p : positions) {
            land[p[0]][p[1]] = true;
            boolean[][] seen = new boolean[m][n];
            int count = 0;
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    if (!land[i][j] || seen[i][j]) continue;
                    count++; // new island found, flood it
                    Deque<int[]> q = new ArrayDeque<>();
                    q.offer(new int[] { i, j });
                    seen[i][j] = true;
                    while (!q.isEmpty()) {
                        int[] c = q.poll();
                        for (int[] d : dirs) {
                            int r = c[0] + d[0],
                                col = c[1] + d[1];
                            if (
                                r < 0 ||
                                col < 0 ||
                                r >= m ||
                                col >= n ||
                                !land[r][col] ||
                                seen[r][col]
                            ) continue;
                            seen[r][col] = true;
                            q.offer(new int[] { r, col });
                        }
                    }
                }
            }
            res.add(count);
        }
        return res;
    }
}

