class Solution {

    private int[] parent, size;

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    private boolean union(int a, int b) {
        int ra = find(a),
            rb = find(b);
        if (ra == rb) return false;
        if (size[ra] < size[rb]) {
            int t = ra;
            ra = rb;
            rb = t;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
        return true;
    }

    public List<Integer> numIslands2(int m, int n, int[][] positions) {
        parent = new int[m * n];
        size = new int[m * n];
        for (int i = 0; i < m * n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        boolean[] land = new boolean[m * n];
        int[][] dirs = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } };
        List<Integer> res = new ArrayList<>();
        int count = 0;
        for (int[] p : positions) {
            int r = p[0],
                c = p[1],
                id = r * n + c; // 2D -> 1D id
            if (land[id]) {
                res.add(count);
                continue;
            } // duplicate addition
            land[id] = true;
            count++; // new island on its own
            for (int[] d : dirs) {
                int nr = r + d[0],
                    nc = c + d[1];
                if (nr < 0 || nc < 0 || nr >= m || nc >= n) continue;
                int nid = nr * n + nc;
                if (land[nid] && union(id, nid)) count--; // merged with a neighbouring island
            }
            res.add(count);
        }
        return res;
    }
}

