class Solution {

    private static final int[][] DIRS = {
        { 1, 0 },
        { -1, 0 },
        { 0, 1 },
        { 0, -1 },
    };

    public int largestIsland(int[][] grid) {
        int n = grid.length,
            best = 0;
        boolean hasZero = false;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) continue;
                hasZero = true;
                grid[i][j] = 1; // try the flip
                best = Math.max(best, bfsSize(grid, i, j));
                grid[i][j] = 0; // undo
            }
        }
        return hasZero ? best : n * n; // all land: whole grid is one island
    }

    private int bfsSize(int[][] grid, int sr, int sc) {
        int n = grid.length,
            size = 0;

        boolean[][] seen = new boolean[n][n];
        Deque<int[]> q = new ArrayDeque<>();
        q.offer(new int[] { sr, sc });
        seen[sr][sc] = true;
        while (!q.isEmpty()) {
            int[] c = q.poll();
            size++;
            for (int[] d : DIRS) {
                int r = c[0] + d[0],
                    col = c[1] + d[1];
                if (
                    r < 0 ||
                    col < 0 ||
                    r >= n ||
                    col >= n ||
                    seen[r][col] ||
                    grid[r][col] == 0
                ) continue;
                seen[r][col] = true;
                q.offer(new int[] { r, col });
            }
        }
        return size;
    }
}

