var largestIsland = function (grid) {
    const n = grid.length;
    const DIRS = [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
    ];
    const bfsSize = (sr, sc) => {
        const seen = Array.from({ length: n }, () =>
            new Array(n).fill(false),
        );
        const q = [[sr, sc]];
        seen[sr][sc] = true;
        for (let head = 0; head < q.length; head++) {
            const [r, c] = q[head];
            for (const [dr, dc] of DIRS) {
                const nr = r + dr,
                    nc = c + dc;
                if (
                    nr < 0 ||
                    nc < 0 ||
                    nr >= n ||
                    nc >= n ||
                    seen[nr][nc] ||
                    grid[nr][nc] === 0
                )
                    continue;
                seen[nr][nc] = true;
                q.push([nr, nc]);
            }
        }
        return q.length; // every cell pushed once
    };
    let best = 0,
        hasZero = false;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) continue;
            hasZero = true;
            grid[i][j] = 1;
            best = Math.max(best, bfsSize(i, j));
            grid[i][j] = 0;
        }
    }
    return hasZero ? best : n * n;
};

