class Solution {
    private int[] parent, size;

    private int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }

    private void union(int a, int b) {
        int ra = find(a), rb = find(b);
        if (ra == rb) return;
        if (size[ra] < size[rb]) { int t = ra; ra = rb; rb = t; }
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    public int largestIsland(int[][] grid) {
        int n = grid.length;
        parent = new int[n * n];
        size = new int[n * n];
        for (int i = 0; i < n * n; i++) { parent[i] = i; size[i] = 1; }
        // 1) build islands
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 0) continue;
                if (r + 1 < n && grid[r + 1][c] == 1) union(r * n + c, (r + 1) * n + c);
                if (c + 1 < n && grid[r][c + 1] == 1) union(r * n + c, r * n + c + 1);
            }
        }
        int best = 0;
        for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++)
        if (grid[r][c] == 1) best = Math.max(best, size[find(r * n + c)]); // no flip needed / all
        ones
        // 2) try each zero
        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
        for (int r = 0; r < n; r++) {
            for (int c = 0; c < n; c++) {
                if (grid[r][c] == 1) continue;
                Set<Integer> roots = new HashSet<>(); // distinct neighbouring islands
                for (int[] d : dirs) {
                    int nr = r + d[0], nc = c + d[1];
                    if (nr >= 0 && nc >= 0 && nr < n && nc < n && grid[nr][nc] == 1) roots.add(find(nr * n +
                    nc));
                }
                int total = 1; // the flipped cell itself
                for (int root : roots) total += size[root];
                best = Math.max(best, total);
            }
        }

        return best;
    }
}

